+import test from "node:test";
+import assert from "node:assert/strict";
+import { readFileSync } from "node:fs";
+import { CURRENT_VERSION, migrate } from "../src/db/migrations.js";
+import { memoryStore } from "../src/db/store.js";
+import { app, seed } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+// Receives 8 l of milk (item 2) into the annex fridge; returns the new batch.
+async function stockAnnex(handle) {
+  const order = (await handle({ method: "POST", path: "/orders", body: { supplierId: 2, lines: [{ itemId: 2, qty: 8 }] } })).body;
+  await handle({ method: "POST", path: `/orders/${order.id}/send` });
+  const res = await handle({ method: "POST", path: `/orders/${order.id}/receive`, headers: annex, body: { lots: [{ lot: "AX-1", expires: "2026-10-30", location: "annex-fridge" }] } });
+  assert.equal(res.status, 200);
+  return res.body.batches[0];
+}
+
+test("schema 2 files open with everything in site main", () => {
+  const old = seed();
+  old.schemaVersion = 2;
+  delete old.sites;
+  old.locations = old.locations.filter((l) => l.site === "main").map(({ site, ...l }) => l);
+  const data = migrate(old);
+  assert.equal(data.schemaVersion, CURRENT_VERSION);
+  assert.deepEqual(data.sites, [{ id: "main", name: "Main kitchen" }]);
+  assert.deepEqual(data.locations.map((l) => l.site), ["main", "main", "main"]);
+  assert.equal(data.batches.length, old.batches.length);
+  assert.equal(memoryStore(old).data.schemaVersion, CURRENT_VERSION);
+});
+
+test("the seed has the annex site and its fridge", () => {
+  const data = JSON.parse(readFileSync(new URL("../data/seed.json", import.meta.url), "utf8"));
+  assert.equal(data.schemaVersion, CURRENT_VERSION);
+  assert.deepEqual(data.sites.find((s) => s.id === "annex"), { id: "annex", name: "Annex kitchen" });
+  assert.deepEqual(data.locations.find((l) => l.id === "annex-fridge"), { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+});
+
+test("no header means site main; an unknown site is a 400 of its own", async () => {
+  const { handle } = app();
+  const plain = (await handle({ path: "/batches" })).body;
+  const main = (await handle({ path: "/batches", headers: { "x-larder-site": "main" } })).body;
+  assert.deepEqual(plain, main);
+  assert.equal(plain.length, 9);
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "cellar" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+  assert.match(bad.body.error.message, /cellar/);
+});
+
+test("stock, batches, alerts and stock value are per site; items are shared", async () => {
+  const { handle } = app();
+  const empty = (await handle({ path: "/items", headers: annex })).body;
+  assert.equal(empty.length, 6);
+  assert.ok(empty.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  const mainMilk = (await handle({ path: "/items/2" })).body.onHand;
+  const mainValue = (await handle({ path: "/reports/stock-value" })).body.totalCents;
+
+  const batch = await stockAnnex(handle);
